// Check if boxes are separated (no intersection in any dimension)
if (box1.max.x < box2.min.x || box2.max.x < box1.min.x ||
    box1.max.y < box2.min.y || box2.max.y < box1.min.y ||
    box1.max.z < box2.min.z || box2.max.z < box1.min.z)
{
    return BoxRelation::Separated;
}

// Calculate overlap dimensions
double overlapX = std::min(box1.max.x, box2.max.x) - std::max(box1.min.x, box2.min.x);
double overlapY = std::min(box1.max.y, box2.max.y) - std::max(box1.min.y, box2.min.y);
double overlapZ = std::min(box1.max.z, box2.max.z) - std::max(box1.min.z, box2.min.z);

// Check if boxes are adjacent (touching but no volume overlap)
// Adjacent means at least one dimension has zero overlap
if (overlapX <= 0.0 || overlapY <= 0.0 || overlapZ <= 0.0)
{
    return BoxRelation::Adjacent;
}

// Boxes overlap with positive volume
return BoxRelation::Overlapped; // END_CODE

